import threading
import time
import hashlib
import hmac
import os
import secrets
from dataclasses import dataclass, field
from typing import Dict, Optional
import sqlite3
import copy

SECRET_KEY = os.environ.get('SESSION_SECRET', secrets.token_hex(32))

@dataclass
class Session:
    user_id: str
    role: str
    token: str
    expires_at: float
    nonce: str = field(default_factory=lambda: secrets.token_hex(16))

class SessionStore:
    def __init__(self):
        self._lock = threading.Lock()
        self._sessions: Dict[str, Session] = {}

    def create_session(self, user_id: str, role: str, ttl: int = 3600) -> str:
        token = secrets.token_urlsafe(32)
        with self._lock:
            self._sessions[token] = Session(
                user_id=user_id,
                role=role,
                token=token,
                expires_at=time.time() + ttl
            )
        return token

    def get_session(self, token: str) -> Optional[Session]:
        with self._lock:
            session = self._sessions.get(token)
            if session and session.expires_at > time.time():
                return copy.copy(session)
            elif session:
                del self._sessions[token]
            return None

    def update_session_role(self, token: str, new_role: str) -> bool:
        with self._lock:
            session = self._sessions.get(token)
            if session:
                session.role = new_role
                return True
            return False

    def revoke_session(self, token: str):
        with self._lock:
            self._sessions.pop(token, None)

store = SessionStore()

def compute_request_mac(method: str, path: str, body: bytes, session_nonce: str) -> str:
    msg = f"{method}:{path}:{body.hex()}:{session_nonce}".encode()
    return hmac.new(SECRET_KEY.encode(), msg, hashlib.sha256).hexdigest()

def validate_request_integrity(method: str, path: str, body: bytes, 
                                provided_mac: str, session: Session) -> bool:
    expected = compute_request_mac(method, path, body, session.nonce)
    return hmac.compare_digest(expected, provided_mac)

class RequestContext:
    def __init__(self, token: str, method: str, path: str, body: bytes, mac: str):
        self.token = token
        self.method = method
        self.path = path
        self.body = body
        self.mac = mac
        self._validated_session: Optional[Session] = None

    def authenticate(self) -> bool:
        """Validate session and request integrity."""
        session = store.get_session(self.token)
        if session is None:
            return False
        # Validate HMAC integrity of the request
        if not validate_request_integrity(
            self.method, self.path, self.body, self.mac, session
        ):
            return False
        # Store snapshot of validated session for authorization check
        self._validated_session = session
        return True

    def authorize(self, required_role: str) -> bool:
        """Check if authenticated session has required role."""
        if self._validated_session is None:
            return False
        # Check role against the validated session snapshot
        return self._validated_session.role == required_role

    def get_user_id(self) -> Optional[str]:
        if self._validated_session:
            return self._validated_session.user_id
        return None

def handle_admin_action(ctx: RequestContext) -> dict:
    """Process an admin-only action with full auth chain."""
    if not ctx.authenticate():
        return {"error": "Authentication failed", "status": 401}

    if not ctx.authorize("admin"):
        return {"error": "Insufficient privileges", "status": 403}

    # Perform privileged action
    return {"result": "Admin action executed", "user": ctx.get_user_id(), "status": 200}

def handle_role_change(token: str, new_role: str) -> dict:
    """Endpoint to change a user's own role (e.g., from preferences).
    In practice this would have its own authorization, but simplified here.
    Only allows changing to 'viewer' or 'editor' roles."""
    allowed_roles = {'viewer', 'editor'}
    if new_role not in allowed_roles:
        return {"error": "Invalid role", "status": 400}

    if store.update_session_role(token, new_role):
        return {"result": f"Role updated to {new_role}", "status": 200}
    return {"error": "Session not found", "status": 404}

