def init_db():
    conn = sqlite3.connect(':memory:')
    conn.execute('CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, user_id TEXT, action TEXT, timestamp REAL)')
    conn.commit()
    return conn

def log_action(conn: sqlite3.Connection, user_id: str, action: str):
    conn.execute(
        'INSERT INTO audit_log (user_id, action, timestamp) VALUES (?, ?, ?)',
        (user_id, action, time.time())
    )
    conn.commit()
